        /// <example>
        /// // Add the following duration to 1 September 2014, 10:19:50
        /// const result = add(new Date(2014, 8, 1, 10, 19, 50), {
        ///   years: 2,
        ///   months: 9,
        ///   weeks: 1,
        ///   days: 7,
        ///   hours: 5,
        ///   minutes: 9,
        ///   seconds: 30,
        /// })
        /// //=> Thu Jun 15 2017 15:29:20
        /// </example>
        /// <example>
        /// // Using Temporal:
        /// // Add the following duration to 1 September 2014, 10:19:50
        /// Temporal.PlainDateTime.from("2014-09-01T10:19:50")
        ///   .add({
        ///     years: 2,
        ///     months: 9,
        ///     weeks: 1,
        ///     days: 7,
        ///     hours: 5,
        ///     minutes: 9,
        ///     seconds: 30,
        ///   })
        ///   .toString();
