    module areIntervalsOverlapping =

        [<AbstractClass>]
        [<Erase>]
        type Exports =
            /// <example>
            /// // For overlapping time intervals:
            /// areIntervalsOverlapping(
            ///   { start: new Date(2014, 0, 10), end: new Date(2014, 0, 20) },
            ///   { start: new Date(2014, 0, 17), end: new Date(2014, 0, 21) }
            /// )
            /// //=> true
            /// </example>
            /// <example>
            /// // For non-overlapping time intervals:
            /// areIntervalsOverlapping(
            ///   { start: new Date(2014, 0, 10), end: new Date(2014, 0, 20) },
            ///   { start: new Date(2014, 0, 21), end: new Date(2014, 0, 22) }
            /// )
            /// //=> false
            /// </example>
            /// <example>
            /// // For adjacent time intervals:
            /// areIntervalsOverlapping(
            ///   { start: new Date(2014, 0, 10), end: new Date(2014, 0, 20) },
            ///   { start: new Date(2014, 0, 20), end: new Date(2014, 0, 30) }
            /// )
            /// //=> false
            /// </example>
            /// <example>
            /// // Using the inclusive option:
            /// areIntervalsOverlapping(
            ///   { start: new Date(2014, 0, 10), end: new Date(2014, 0, 20) },
            ///   { start: new Date(2014, 0, 20), end: new Date(2014, 0, 24) },
            ///   { inclusive: true }
            /// )
            /// //=> true
            /// </example>
            /// <param name="intervalLeft">
            /// The first interval to compare.
            /// </param>
            /// <param name="intervalRight">
            /// The second interval to compare.
            /// </param>
            /// <param name="options">
            /// The object with options
            /// </param>
            /// <returns>
            /// Whether the time intervals are overlapping
            /// </returns>
            [<Import("areIntervalsOverlapping", "date-fns")>]
            static member areIntervalsOverlapping (intervalLeft: DateFns.Interval, intervalRight: DateFns.Interval, ?options: DateFns.areIntervalsOverlapping.AreIntervalsOverlappingOptions) : bool = nativeOnly

